CREATE TABLE project_update_reads(user_id INTEGER NOT NULL REFERENCES users(id),project_id INTEGER NOT NULL REFERENCES short_video_accounts(id),kind TEXT NOT NULL,record_id INTEGER NOT NULL,token TEXT NOT NULL,PRIMARY KEY(user_id,project_id,kind,record_id));

-- Existing history starts read; outstanding review tasks remain counted independently.
INSERT OR IGNORE INTO project_update_reads(user_id,project_id,kind,record_id,token) SELECT c.creator_id,c.project_id,'cross',c.id,CAST(coalesce((SELECT max(e.id) FROM cross_events e WHERE e.record_id=c.id AND e.actor_id<>c.creator_id),0) AS TEXT) FROM cross_records c;
INSERT OR IGNORE INTO project_update_reads(user_id,project_id,kind,record_id,token) SELECT c.uploader_user_id,c.account_id,'video',c.id,CAST(coalesce((SELECT max(r.id) FROM reviews r WHERE r.content_id=c.id AND r.reviewer_user_id<>c.uploader_user_id),0) AS TEXT)||':'||CAST(coalesce((SELECT max(e.id) FROM publishing_events e WHERE e.content_id=c.id AND e.operator_user_id<>c.uploader_user_id),0) AS TEXT) ||':'||CAST(coalesce((SELECT max(a.id) FROM audit_logs a WHERE a.object_type='content' AND coalesce(a.user_id,0)<>c.uploader_user_id AND (a.object_id=CAST(c.id AS TEXT) OR instr(','||a.object_id||',',','||c.code||',')>0)),0) AS TEXT) FROM contents c WHERE c.account_id IS NOT NULL;
